const p = $input.first().json.payload;
const evento = p.scheduled_event;

const nome_completo = p.name?.trim() ?? "";
const primeiro_nome = p.first_name?.trim() ?? "";
const ultimo_nome   = p.last_name?.trim() ?? "";
const email         = p.email?.trim().toLowerCase() ?? "";

const qa       = p.questions_and_answers ?? [];
const telefone = qa.find(q => q.position === 0)?.answer?.trim() ?? "";

// Número para a Evolution API precisa do indicativo — o CRM guarda o
// telefone sem indicativo (normalizarTelefone remove-o), mas o envio de
// WhatsApp ao cliente falha sem ele (JID resolve para um número inválido).
const telefone_digitos = telefone.replace(/\D/g, "");
const telefone_whatsapp = telefone_digitos.length === 9 ? `351${telefone_digitos}` : telefone_digitos.replace(/^00/, "");

const evento_nome = evento.name?.trim() ?? "";
const is_drenagem  = evento_nome.toLowerCase().includes("drenagem");
const is_gift_card = evento_nome.toLowerCase().includes("voucher");
const is_casal     = evento_nome.toLowerCase().includes("a dois");

let categoria;
if (is_drenagem)       categoria = "drenagem_linfatica";
else if (is_gift_card) categoria = "gift_card";
else if (is_casal)     categoria = "massagem_relaxamento_casal";
else                   categoria = "massagem_relaxamento";

const MAP_DRENAGEM = {
  "1.ª sessão (90 min)":     "primeira_sessao_90",
  "1.ª sessão (60 min)":     "primeira_sessao_60",
  "pack premium (90 min)":   "pack_90",
  "sessão de pack (60 min)": "pack_60",
};

let subtipo_drenagem = null;
if (is_drenagem) {
  for (const [chave, valor] of Object.entries(MAP_DRENAGEM)) {
    if (evento_nome.toLowerCase().includes(chave.toLowerCase())) {
      subtipo_drenagem = valor;
      break;
    }
  }
}

const servico_raw = is_drenagem || is_gift_card
  ? evento_nome
  : (qa.find(q => q.position === 1)?.answer?.trim() ?? "");

const MAP_SERVICO = {
  "puro aroma":     "Puro Aroma",
  "essência plena": "Essência Plena",
  "cera quente":    "Cera Quente",
};

let servico_nome = evento_nome;
if (is_gift_card) {
  const codigo_voucher = qa.find(q => q.position === 1)?.answer?.trim() ?? null;
  servico_nome = codigo_voucher ? `Voucher Essence Wellness — ${codigo_voucher}` : "Voucher Essence Wellness";
} else {
  for (const [chave, valor] of Object.entries(MAP_SERVICO)) {
    if (servico_raw.toLowerCase().includes(chave.toLowerCase())) {
      servico_nome = is_casal ? `Massagem a Dois — ${valor}` : valor;
      break;
    }
  }
}

const start_raw   = evento.start_time ?? "";
const end_raw     = evento.end_time ?? "";
const data_inicio = new Date(start_raw);
const data_fim    = new Date(end_raw);
const duracao_min = Math.round((data_fim - data_inicio) / 60000);

const hora_lisboa = data_inicio.toLocaleString("pt-PT", {
  timeZone: "Europe/Lisbon",
  day: "2-digit", month: "2-digit", year: "numeric",
  hour: "2-digit", minute: "2-digit",
});

// UUID do evento Calendly — usado para cancelamento
const calendly_event_id = (evento.uri ?? "").split("/").pop() ?? null;

return [{
  json: {
    cliente: { nome_completo, primeiro_nome, ultimo_nome, email, telefone, telefone_whatsapp },
    sessao: { evento_nome, servico_raw, servico_nome, categoria, subtipo_drenagem, is_drenagem, is_gift_card, is_casal, codigo_voucher: is_gift_card ? (qa.find(q => q.position === 1)?.answer?.trim() ?? null) : null, data_inicio_utc: start_raw, data_fim_utc: end_raw, duracao_minutos: duracao_min, hora_lisboa },
    calendly: { event_uri: evento.uri, invitee_uri: p.uri, cancel_url: p.cancel_url, reschedule_url: p.reschedule_url, event_id: calendly_event_id, old_invitee: p.old_invitee ?? null },
  }
}];

