const p = $json.payload;
const eventUri = p.event || (p.scheduled_event && p.scheduled_event.uri) || '';
const calendlyEventId = eventUri.split('/').pop() || null;
const rescheduled = !!p.rescheduled;
const nomeCliente = p.name || '';

return [{ json: { calendlyEventId, rescheduled, nomeCliente } }];

const s = $json.data[0];
const original = $('Processar Cancelamento').item.json;
return [{ json: { sessaoId: s.id, servico: s.servico, data: s.data, hora: s.hora, rescheduled: original.rescheduled, nomeCliente: original.nomeCliente } }];

const d = $('Extrair Sessão Encontrada').item.json;
const dataObj = d.data ? new Date(d.data) : null;
const dataFmt = dataObj ? dataObj.toLocaleDateString('pt-PT', { day: '2-digit', month: 'long' }) : '';
const numeroBea = '351911150025';
const texto = d.rescheduled
  ? ('🔄 *' + d.nomeCliente + '* remarcou a sessão' + (d.servico ? ' de ' + d.servico : '') + (dataFmt ? ' que estava marcada para ' + dataFmt + (d.hora ? ' às ' + d.hora : '') : '') + '. Uma nova marcação deve chegar a seguir — verifica o CRM daqui a pouco.')
  : ('❌ *' + d.nomeCliente + '* cancelou a sessão' + (d.servico ? ' de ' + d.servico : '') + (dataFmt ? ' marcada para ' + dataFmt + (d.hora ? ' às ' + d.hora : '') : '') + ' via Calendly.');
return [{ json: { texto, numeroBea } }];

const r = $json.resource || $json;
const eventUri = r.event || '';
const calendlyEventIdAntigo = eventUri.split('/').pop() || null;
return [{ json: { calendlyEventIdAntigo } }];

const s = $('Processar Dados da Marcação').item.json;
const dataFmt = new Date(s.sessao.data_inicio_utc).toLocaleDateString('pt-PT', { day:'2-digit', month:'long', timeZone:'Europe/Lisbon' });
const horaFmt = new Date(s.sessao.data_inicio_utc).toLocaleTimeString('pt-PT', { hour:'2-digit', minute:'2-digit', hour12:false, timeZone:'Europe/Lisbon' });
const texto = `Olá *${s.cliente.primeiro_nome}*! 🌸\n\nA tua sessão de *${s.sessao.servico_nome}* foi reagendada para *${dataFmt}, às ${horaFmt}*. Já está tudo tratado da minha parte — não precisas de preencher nada outra vez. ✨\n\nAté breve! 🤍`;
return [{ json: { texto, telefone_whatsapp: s.cliente.telefone_whatsapp } }];

const s = $('Processar Dados da Marcação').item.json;
const dataFmt = new Date(s.sessao.data_inicio_utc).toLocaleDateString('pt-PT', { day:'2-digit', month:'long', timeZone:'Europe/Lisbon' });
const horaFmt = new Date(s.sessao.data_inicio_utc).toLocaleTimeString('pt-PT', { hour:'2-digit', minute:'2-digit', hour12:false, timeZone:'Europe/Lisbon' });
const texto = `🔄 *${s.cliente.nome_completo}* reagendou a sessão de ${s.sessao.servico_nome} para *${dataFmt} às ${horaFmt}*. Já está tudo atualizado no CRM — terapeuta e preço mantiveram-se.`;
const numeroBea = '351911150025';
return [{ json: { texto, numeroBea } }];

// So faz sentido para marcacoes de gift card — para as outras 3
// categorias devolve os dados tal como vieram, sem tocar em nada.
const dados = $('Processar Dados da Marcação').item.json;

if (!dados.sessao.is_gift_card) {
  return [{ json: dados }];
}

const resposta = $json;
const lista = (resposta && resposta.data) || [];
const codigo = (dados.sessao.codigo_voucher || '').toUpperCase().trim();
const encontrado = lista.find(v => (v.codigo || '').toString().trim().toUpperCase() === codigo);

let voucher_status = 'nao_encontrado';
let voucher_id = null;
let servico_nome = dados.sessao.servico_nome;

if (encontrado) {
  const estado = (encontrado.estado || '').toString().trim().toLowerCase();
  if (estado === 'ativo') {
    voucher_status = 'valido';
    voucher_id = encontrado.id;
    servico_nome = `Voucher — ${encontrado.servicoNome}`;
  } else {
    voucher_status = estado === 'expirado' ? 'expirado' : 'ja_utilizado';
  }
}

return [{
  json: {
    ...dados,
    sessao: { ...dados.sessao, servico_nome, voucher_status, voucher_id },
  },
}];

// Fallback: o WhatsApp falhou — reconstrói a mesma mensagem para email.
